{ name, port ? 4000, debug ? false, ... }:
{
  label = "${name}:${toString port}";
  inherit debug;
}

let
  mkService = import ./mkService.nix;
in {
  services = map (name: mkService { inherit name; }) [ "web" "admin" ];
  worker = mkService { name = "worker"; port = 4100; };
}

let
  take = n: l: if n == 0 then [] else [ l.head ] ++ take (n - 1) l.tail;
  nat = n: { head = n; tail = nat (n + 1); };
in take 4 (nat 0)

derivation {
  name = "hello-note";
  system = builtins.currentSystem;
  builder = "/bin/sh";
  args = [ "-c" "echo \"$greeting\" > $out" ];
  greeting = "hello from a raw derivation";
}

let
  note = derivation {
    name = "note";
    system = builtins.currentSystem;
    builder = "/bin/sh";
    args = [ "-c" "echo hello > $out" ];
  };
in derivation {
  name = "shout";
  system = builtins.currentSystem;
  builder = "/bin/sh";
  args = [ "-c" "read word < ${note}; echo \"$word, world\" > $out" ];
}

